import fs from 'node:fs'
import { defineConfig } from 'astro/config'
import starlight from '@astrojs/starlight'
import { SITE_URL, SITE_TITLE, SITE_DESCRIPTION, GITHUB_URL, DISCORD_URL, GITHUB_BRANCH, INSTALL } from './config/site.mjs'
import { baseLinks } from './config/base-links.mjs'
import { externalLinks } from './config/external-links.mjs'

// Generated by `npm run sync` — run it after changing the spec.
const core = JSON.parse(fs.readFileSync('./src/data/core.json', 'utf8')) as {
  classes: {
    id: string
    slug: string
    url: string
    members: { name: string; slug: string; url: string }[]
  }[]
}

// Configuration and CLI pages, from src/data/reference.json, one sidebar
// group per page group in the order the data lists them.
const reference = JSON.parse(fs.readFileSync('./src/data/reference.json', 'utf8')) as {
  pages: { area: 'config' | 'cli'; url: string; title: string; group: string }[]
}
const referenceSidebar = (area: 'config' | 'cli') => {
  const groups = new Map<string, { label: string; link: string }[]>()
  for (const p of reference.pages.filter((p) => p.area === area)) {
    if (!groups.has(p.group)) groups.set(p.group, [])
    groups.get(p.group)!.push({ label: p.title.replace(/`/g, ''), link: p.url })
  }
  return [...groups].map(([label, items]) => ({ label, collapsed: true, items }))
}

// Syntax highlighting for Novis code fences (```novis / ```nvs). `npm run sync:render` writes this
// file from the editors' grammar.
const novisGrammar = JSON.parse(fs.readFileSync('./config/novis.tmLanguage.json', 'utf8'))

const coreSidebar = core.classes.map((cls) => ({
  label: cls.id.replace(/\./g, '\\'),
  collapsed: true,
  items: [
    { label: 'Overview', link: cls.url },
    ...cls.members.map((m) => ({ label: m.name, link: m.url })),
  ],
}))

export default defineConfig({
  site: SITE_URL,
  // Deploying under a subfolder: set ASTRO_BASE, or pass `--base /sub/` on
  // the CLI (which overrides the env var) for a one-off build, and every
  // link and asset URL gets the prefix — sidebar/nav via Starlight, content
  // links via the baseLinks() integration below, component links via
  // src/lib/base.ts. Unset, the site builds for the webroot as before.
  base: process.env.ASTRO_BASE,
  trailingSlash: 'ignore',
  integrations: [
    baseLinks(),
    externalLinks(),
    starlight({
      title: SITE_TITLE,
      description: SITE_DESCRIPTION,
      // The mark in the header replaces the wordmark and links to the home
      // page. Its alt text keeps the title for screen readers. One source
      // of truth: media/novis-logo.png is the design export, sized down by
      // CSS in src/components/Header.astro. public/favicon.ico and
      // public/apple-touch-icon.png are cut from the same file — see the
      // website README's "Logo and favicon" section for the command.
      logo: { src: './media/novis-logo.png', alt: SITE_TITLE, replacesTitle: true },
      favicon: '/favicon.ico',
      customCss: ['./src/styles/custom.css'],
      routeMiddleware: './src/routeData.ts',
      social: [
        { icon: 'github', label: 'GitHub', href: GITHUB_URL },
        { icon: 'discord', label: 'Discord', href: DISCORD_URL },
      ],
      editLink: {
        // Handwritten docs pages get an edit link; generated pages opt out
        // with `editUrl: false` in their frontmatter.
        baseUrl: `${GITHUB_URL}/edit/${GITHUB_BRANCH}/website/`,
      },
      // No "Last updated" stamp: it is the git commit date, and a page that is still correct
      // reads as stale the moment something near it is edited. `git log` is the changelog.
      lastUpdated: false,
      components: {
        Header: './src/components/Header.astro',
        Footer: './src/components/Footer.astro',
        Sidebar: './src/components/Sidebar.astro',
        Head: './src/components/Head.astro',

        MobileMenuFooter: './src/components/MobileMenuFooter.astro',
        // The mobile menu button on every page, sidebar or not.
        PageFrame: './src/components/PageFrame.astro',
        // The two Starlight components that link off the site, with the
        // external-link rule applied — see config/external-links.mjs.
        SocialIcons: './src/components/SocialIcons.astro',
        EditLink: './src/components/EditLink.astro',
      },
      expressiveCode: {
        shiki: {
          langs: [novisGrammar],
        },
        styleOverrides: {
          // A code block's frame already follows the site's colors (Starlight
          // hands Expressive Code its UI tokens), but the code surface itself
          // comes from the syntax theme — a cold grey under a warm page. The
          // value is --nv-code-bg in src/styles/custom.css, with the rest of
          // the palette.
          codeBackground: 'var(--nv-code-bg)',
        },
      },
      head: [
        // The palette's accent, as it appears in the light theme — the browser
        // chrome sits above a light page. Kept in step with --nv-accent in
        // src/styles/custom.css, which is where the palette lives.
        { tag: 'meta', attrs: { name: 'theme-color', content: '#b20038' } },
        { tag: 'meta', attrs: { property: 'og:site_name', content: SITE_TITLE } },
      ],
      // One top-level group per area, labelled as AREAS and INSTALL in
      // config/site.mjs. A page shows only the group of the area its URL is
      // in: src/routeData.ts picks it, and a page outside every area has no
      // sidebar.
      sidebar: [
        {
          label: 'Guides',
          items: [{ label: 'Overview', link: '/guides/' }],
        },
        {
          label: 'Syntax',
          items: [
            { label: 'Overview', link: '/syntax/' },
            { label: 'Start here', link: '/syntax/start-here/' },
            {
              label: 'Basics',
              items: [
                { label: 'Files and statements', link: '/syntax/basics/files-and-statements/' },
                { label: 'Comments and doc comments', link: '/syntax/basics/comments/' },
                { label: 'Variables and var', link: '/syntax/basics/variables/' },
                { label: 'Constants', link: '/syntax/basics/constants/' },
              ],
            },
            {
              label: 'Values and types',
              items: [
                { label: 'Numbers', link: '/syntax/values/numbers/' },
                { label: 'Strings and interpolation', link: '/syntax/values/strings/' },
                { label: 'Bool and null', link: '/syntax/values/bool-and-null/' },
                { label: 'Arrays and array<T>', link: '/syntax/values/arrays/' },
                { label: 'Nullable types', link: '/syntax/values/nullable/' },
                { label: 'Union types', link: '/syntax/values/union-types/' },
                { label: 'Enums', link: '/syntax/values/enums/' },
                { label: 'Converting with as', link: '/syntax/values/as/' },
                { label: 'Type tests with is', link: '/syntax/values/is/' },
                { label: 'Tainted and secret strings', link: '/syntax/values/tainted-and-secret/' },
              ],
            },
            {
              label: 'Operators',
              items: [
                { label: 'Arithmetic and assignment', link: '/syntax/operators/arithmetic/' },
                { label: 'Comparison and logic', link: '/syntax/operators/comparison/' },
                { label: '?? and ??=', link: '/syntax/operators/null-coalescing/' },
                { label: 'String operators', link: '/syntax/operators/string-operators/' },
                { label: 'The pipeline operator |>', link: '/syntax/operators/pipeline/' },
                { label: 'Precedence', link: '/syntax/operators/precedence/' },
              ],
            },
            {
              label: 'Control flow',
              items: [
                { label: 'if and else', link: '/syntax/control-flow/if/' },
                { label: 'match', link: '/syntax/control-flow/match/' },
                { label: 'switch', link: '/syntax/control-flow/switch/' },
                { label: 'while and for', link: '/syntax/control-flow/loops/' },
                { label: 'foreach', link: '/syntax/control-flow/foreach/' },
                { label: 'Iterators and generators', link: '/syntax/control-flow/iterators/' },
                { label: 'break, continue and return', link: '/syntax/control-flow/break-continue-return/' },
                { label: 'echo, unset and exit', link: '/syntax/control-flow/other-statements/' },
              ],
            },
          ],
        },
        {
          label: 'Reference',
          items: [
            { label: 'Overview', link: '/reference/' },
            {
              label: 'Core classes',
              items: [{ label: 'All classes', link: '/reference/core/' }, ...coreSidebar],
            },
            {
              label: 'Configuration',
              items: [{ label: 'All blocks', link: '/reference/config/' }, ...referenceSidebar('config')],
            },
            {
              label: 'CLI commands',
              items: [{ label: 'All commands', link: '/reference/cli/' }, ...referenceSidebar('cli')],
            },
          ],
        },
        {
          label: 'In-Depth',
          items: [
            { label: 'Overview', link: '/in-depth/' },
            { label: 'What changed', link: '/in-depth/what-changed/' },
          ],
        },
        {
          label: INSTALL.label,
          items: [
            { label: 'Install Novis', link: INSTALL.href },
            { label: 'Hello, World!', link: '/install/hello-world/' },
          ],
        },
      ],
    }),
  ],
})
